const FIXTURE: &str = include_str!("../testdata/vr-hook.json");
const VR: Address = address!("ff00000000000000000000000000000000000003");
const FEE_COLLECTOR: Address = Address::new([0x77; 20]);

// ---- the provisional profile pins (validator-registry design section 3.3.4)
// ----------------------
//
// VR's immutable per-call caps and its own step allowances, as `src/vr/VRShared.sol` declares them
// (all provisional there). A module's caps are min(its gasBounds, these), so a budget at these caps
// covers every module VR can activate.
const CAP_ELECT: u64 = 4_000_000;
const CAP_OUTPUT: u64 = 1_000_000;
const CAP_RECORD: u64 = 1_500_000;
const CAP_RESOLVED: u64 = 500_000;
const CAP_ATTACH: u64 = 3_000_000;
const CAP_DETACH: u64 = 500_000;
const CAP_ADOPT: u64 = 1_000_000;
const ELECT_VR_GAS: u64 = 2_600_000;
const VOID_VR_GAS: u64 = 40_000;
const INNER_SLACK: u64 = 5_000;
const OUTER_RESERVE: u64 = 60_000;
/// VR's own work in the worst Boundary (16 installed, 15 activated, the switch and a holder entry):
/// forge `test/vr/VRGas.t.sol` measures 2,221,076 with cheap callbacks.
const G_BOUNDARY_VR: u64 = 2_300_000;

/// The inner call's requirement for a cap (`VRShared._inner`).
const fn inner(cap: u64) -> u64 {
    cap + cap / 63 + INNER_SLACK
}

/// What a contained step requires of `gasleft()` before it calls (`VRShared._contained`).
const fn need(budget: u64) -> u64 {
    budget + budget / 63 + OUTER_RESERVE
}

/// A contained void step at `cap`.
const fn void_need(cap: u64) -> u64 {
    need(inner(cap) + VOID_VR_GAS)
}

/// The contained elect step at the given module caps.
const fn elect_need(cap_elect: u64, cap_output: u64) -> u64 {
    need(inner(cap_elect) + inner(cap_output) + ELECT_VR_GAS)
}

/// Provisional `ElectGas`: the contained elect step at VR's caps, with the 5/4 margin (which also
/// covers VR's gate, the watchdogs and the context before the step).
const ELECT_GAS: u64 = elect_need(CAP_ELECT, CAP_OUTPUT) * 5 / 4;

/// Provisional `HookRecordGas`: the worst record, a Boundary that installs 16 members, activates
/// the bound changes and switches the pointer (onResolved, adoption, the old module's onRecords
/// share, detach and attach, each contained at VR's caps), with the 5/4 margin.
const HOOK_RECORD_GAS: u64 = (G_BOUNDARY_VR +
    void_need(CAP_RESOLVED) +
    void_need(CAP_ADOPT) +
    void_need(CAP_RECORD) +
    void_need(CAP_DETACH) +
    void_need(CAP_ATTACH)) *
    5 /
    4;

// ---- the fixture ------------------------------------------------------------------------------

type Slots = BTreeMap<U256, U256>;

struct Account {
    role: String,
    address: Address,
    code: Bytes,
}

#[derive(Debug)]
struct Expect {
    applied: u64,
    outcome: u8,
    health: u8,
    cursor: u64,
    open_output: B256,
    last_acked: B256,
    active_module: Address,
}

struct Scenario {
    name: String,
    progress: u64,
    uc_time: u64,
    records: Vec<RecordEntry>,
    pre: BTreeMap<Address, Slots>,
    post: BTreeMap<Address, Slots>,
    expect: Expect,
}

struct Fixture {
    origin: B256,
    accounts: Vec<Account>,
    scenarios: Vec<Scenario>,
}

fn word(v: &serde_json::Value) -> U256 {
    U256::from_str_radix(v.as_str().unwrap().trim_start_matches("0x"), 16).unwrap()
}

fn slots(v: &serde_json::Value) -> BTreeMap<Address, Slots> {
    v.as_object()
        .unwrap()
        .iter()
        .map(|(a, s)| {
            let s = s.as_object().unwrap().iter().map(|(k, v)| (word(&k.as_str().into()), word(v)));
            (a.parse().unwrap(), s.collect())
        })
        .collect()
}

fn fixture() -> &'static Fixture {
    static F: OnceLock<Fixture> = OnceLock::new();
    F.get_or_init(|| {
        let f: serde_json::Value = serde_json::from_str(FIXTURE).unwrap();
        assert_eq!(f["format"], "unicity-vr-hook-state-v1");
        assert_eq!(f["chainId"], 1337, "the state was produced on the chain the world runs");
        let accounts = f["accounts"]
            .as_object()
            .unwrap()
            .iter()
            .map(|(role, a)| {
                let code: Bytes = a["code"].as_str().unwrap().parse().unwrap();
                assert_eq!(
                    keccak256(&code),
                    a["codeHash"].as_str().unwrap().parse::<B256>().unwrap(),
                    "{role}"
                );
                Account {
                    role: role.clone(),
                    address: a["address"].as_str().unwrap().parse().unwrap(),
                    code,
                }
            })
            .collect();
        let scenarios = f["scenarios"]
            .as_object()
            .unwrap()
            .iter()
            .map(|(name, s)| {
                assert_eq!(
                    s["blockNumber"], 1,
                    "{name}: forge ran the hooks at the ureth block number"
                );
                let mut records: Vec<RecordEntry> = Vec::new();
                for r in s["records"].as_array().unwrap() {
                    let predecessor = records.last().map_or(B256::ZERO, |e| e.record_id);
                    let entry = testing::record_entry(
                        r["index"].as_u64().unwrap(),
                        predecessor,
                        r["kind"].as_u64().unwrap() as u8,
                        r["progress"].as_u64().unwrap(),
                        r["ucTime"].as_u64().unwrap(),
                        r["data"].as_str().unwrap().parse::<Bytes>().unwrap().to_vec(),
                    );
                    assert_eq!(
                        entry.record_id,
                        r["recordId"].as_str().unwrap().parse::<B256>().unwrap(),
                        "{name}: the identifier forge computed is the one this crate computes"
                    );
                    assert_eq!(
                        entry.predecessor,
                        r["predecessor"].as_str().unwrap().parse::<B256>().unwrap()
                    );
                    records.push(entry);
                }
                let pre = slots(&s["pre"]);
                let mut post = pre.clone();
                for (address, changed) in slots(&s["changed"]) {
                    let account = post.entry(address).or_default();
                    for (k, v) in changed {
                        if v.is_zero() {
                            account.remove(&k);
                        } else {
                            account.insert(k, v);
                        }
                    }
                }
                post.retain(|_, s| !s.is_empty());
                let e = &s["expect"];
                Scenario {
                    name: name.clone(),
                    progress: s["progress"].as_u64().unwrap(),
                    uc_time: s["ucTime"].as_u64().unwrap(),
                    records,
                    pre,
                    post,
                    expect: Expect {
                        applied: e["applied"].as_u64().unwrap(),
                        outcome: e["outcome"].as_u64().unwrap() as u8,
                        health: e["health"].as_u64().unwrap() as u8,
                        cursor: e["cursor"].as_u64().unwrap(),
                        open_output: e["openOutput"].as_str().unwrap().parse().unwrap(),
                        last_acked: e["lastAcked"].as_str().unwrap().parse().unwrap(),
                        active_module: e["activeModule"].as_str().unwrap().parse().unwrap(),
                    },
                }
            })
            .collect();
        Fixture { origin: f["origin"].as_str().unwrap().parse().unwrap(), accounts, scenarios }
    })
}

fn scenario(name: &str) -> &'static Scenario {
    fixture().scenarios.iter().find(|s| s.name == name).unwrap_or_else(|| panic!("no {name}"))
}

fn account(role: &str) -> Address {
    fixture().accounts.iter().find(|a| a.role == role).unwrap().address
}

// ---- the world --------------------------------------------------------------------------------

/// Block 1 over the signed genesis with the scenario's accounts allocated, importing the
/// scenario's records at its progress and UC time.
struct World {
    provider: FixtureProvider,
    parent: SealedHeader<alloy_consensus::Header>,
    root: RootInputV2,
    chain_spec: Arc<ChainSpec>,
    import: Bytes,
    update: Bytes,
}

impl World {
    fn new(s: &Scenario) -> Self {
        let genesis: Genesis =
            serde_json::from_str(include_str!("../testdata/signed-beacon-genesis.json")).unwrap();
        let chain_spec = Arc::new(ChainSpec::from_genesis(genesis));
        let parent = SealedHeader::new(chain_spec.genesis_header().clone(), genesis_hash());
        let mut provider = FixtureProvider::signed_genesis();
        provider.set_block_hash(0, genesis_hash());
        for a in &fixture().accounts {
            let storage: Vec<(U256, U256)> =
                s.pre.get(&a.address).into_iter().flatten().map(|(k, v)| (*k, *v)).collect();
            provider.insert_contract(a.address, a.code.clone(), U256::ZERO, &storage);
        }
        let import: Bytes = RecordImport {
            progress: s.progress,
            uc_time: s.uc_time,
            target_count: s.records.len() as u64,
            target_tip: s.records.last().map_or(B256::ZERO, |e| e.record_id),
            entries: s.records.clone(),
        }
        .to_bytes()
        .into();
        let mut root = input(1, 1, genesis_hash());
        let update = testing::seal_with_import(&mut root, 0, GENESIS_TAIL, &import);
        assert_eq!(
            root.origin_identity().unwrap(),
            fixture().origin,
            "forge elected under the origin identity this block carries"
        );
        Self { provider, parent, root, chain_spec, import, update }
    }

    /// The block profile whose system reservation is the base one plus exactly the hook envelope.
    fn profile(&self, hook: &RecordsHook) -> BlockProfile {
        let base = profile();
        let envelope = hook.envelope_gas().unwrap();
        BlockProfile {
            system_gas: base.system_gas + envelope,
            max_gas: base.max_gas + envelope,
            ..base
        }
    }

    fn attributes(&self, hook: &RecordsHook) -> NextBlockEnvAttributes {
        NextBlockEnvAttributes {
            timestamp: derive_timestamp(self.root.origin.reference_time, self.parent.timestamp)
                .unwrap(),
            suggested_fee_recipient: FEE_COLLECTOR,
            prev_randao: derive_prev_randao(
                self.root.origin.root_round,
                self.root.authorized_round,
            ),
            gas_limit: self.profile(hook).max_gas,
            parent_beacon_block_root: Some(derive_beacon_root(
                self.root.origin.root_round,
                self.root.authorized_round,
            )),
            withdrawals: Some(Default::default()),
            extra_data: self.root.input_commitment().unwrap().to_vec().into(),
            slot_number: None,
        }
    }

    fn config(&self, hook: RecordsHook) -> UnicityEvmConfig {
        let mut job =
            B1Job { context: context(), update: self.update.clone(), records: self.import.clone() };
        job.context.hook = hook;
        let bound = Arc::new(
            BoundExecutionInput::from_validated_genesis(
                Arc::new(self.root.clone()),
                job,
                self.profile(&hook),
                &self.parent,
                genesis_hash(),
                FEE_COLLECTOR,
            )
            .unwrap(),
        );
        UnicityEvmConfig::new(
            unicity_eth_config(self.chain_spec.clone(), &testing::b1_context()),
            bound,
        )
    }

    /// Builds block 1 through the real block path and returns it with the state after it.
    fn build(&self, hook: RecordsHook) -> Result<(CompletedBuild, FixtureProvider), String> {
        let config = self.config(hook);
        let mut state =
            State::builder().with_database(self.provider.clone()).with_bundle_update().build();
        let built = build_complete(
            &config,
            &self.parent,
            self.attributes(&hook),
            &mut state,
            self.provider.clone(),
            vec![],
        )
        .map_err(|e| e.to_string())?;
        let mut after = self.provider.clone();
        after.apply_bundle(&state.bundle_state);
        Ok((built, after))
    }

    /// The state the hooks start from: the block built without them (the records imported, finalize
    /// and EIP-4788 done). The registry's words do not depend on the hook (`block_adapter.rs`).
    fn before_hooks(&self) -> (FixtureProvider, HookEnv) {
        let (built, before) = self.build(RecordsHook::default()).unwrap();
        let header = built.outcome.block.header();
        (before, HookEnv::at(1337, header.number, header.timestamp))
    }
}

/// ureth's hook (`run_hooks`, the function the block executor calls) run directly on `before`
/// within `budget`, returning what it reported and the state after it.
fn hooks_on(
    before: &FixtureProvider,
    env: &HookEnv,
    hook: &RecordsHook,
    budget: u64,
) -> Result<(HookOutcome, FixtureProvider), String> {
    let mut state = State::builder().with_database(before.clone()).with_bundle_update().build();
    let outcome =
        run_hooks(&mut state, hook, env, fixture().origin, budget).map_err(|e| format!("{e:?}"))?;
    state.merge_transitions(BundleRetention::PlainState);
    let mut after = before.clone();
    after.apply_bundle(&state.take_bundle());
    Ok((outcome, after))
}

/// The pinned hook of a scenario: VR as the custody and the election, H = the batch (at least
/// one), at the provisional pins.
fn pinned(s: &Scenario) -> RecordsHook {
    RecordsHook {
        custody: VR,
        h_records: (s.records.len() as u32).max(1),
        record_gas: HOOK_RECORD_GAS,
        election: VR,
        elect_gas: ELECT_GAS,
    }
}

/// The slot-for-slot differences between ureth's state and forge's on every fixture account.
fn diff(after: &FixtureProvider, s: &Scenario) -> Vec<String> {
    let mut out = Vec::new();
    for a in &fixture().accounts {
        let got = after.storage_of(a.address);
        let empty = Slots::new();
        let want = s.post.get(&a.address).unwrap_or(&empty);
        for k in got.keys().chain(want.keys()).collect::<std::collections::BTreeSet<_>>() {
            if got.get(k) != want.get(k) {
                out.push(format!(
                    "{} slot {k:#x}: ureth {:?} forge {:?}",
                    a.role,
                    got.get(k),
                    want.get(k)
                ));
            }
        }
    }
    out
}

// ---- views on the state after the block --------------------------------------------------------

sol! {
    function health() external view returns (uint8);
    function recordCursor() external view returns (uint64);
    function openOutput() external view returns (bytes32);
    function lastAcked() external view returns (bytes32);
    function retired(uint8 holder, uint64 id, uint64 generation) external view returns (bool);
    function holderCount() external view returns (uint8);
    function activeModule() external view returns (address module);
    function output(bytes32 resultId) external view returns (uint8 state);
}

/// One read-only call against `state`, from the system caller, discarded.
fn view(state: &FixtureProvider, data: Vec<u8>) -> Bytes {
    let mut evm = Context::mainnet()
        .modify_cfg_chained(|cfg| {
            cfg.chain_id = 1337;
            cfg.set_spec_and_mainnet_gas_params(SpecId::CANCUN)
        })
        .with_db(state.clone())
        .build_mainnet();
    let mut tx = TxEnv::new_system_tx_with_caller(SYSTEM_CALLER, VR, data.into());
    tx.gas_limit = 30_000_000;
    evm.ctx_mut().set_tx(tx);
    let result = MainnetHandler::<_, revm::context_interface::result::EVMError<_>, _>::default()
        .run_system_call(&mut evm)
        .unwrap();
    assert!(result.is_success(), "{result:?}");
    result.output().cloned().unwrap_or_default()
}

fn health_of(state: &FixtureProvider) -> u8 {
    healthCall::abi_decode_returns(&view(state, healthCall {}.abi_encode())).unwrap()
}

/// The first word of `output(rid)`: the ABI offset of the dynamic struct, then its `state` word.
fn output_state(state: &FixtureProvider, rid: B256) -> u8 {
    let out = view(state, outputCall { resultId: rid }.abi_encode());
    out[63]
}

fn check_views(after: &FixtureProvider, s: &Scenario) {
    let e = &s.expect;
    assert_eq!(health_of(after), e.health, "{}: health", s.name);
    let cursor =
        recordCursorCall::abi_decode_returns(&view(after, recordCursorCall {}.abi_encode()))
            .unwrap();
    assert_eq!(cursor, e.cursor, "{}: cursor", s.name);
    assert_eq!(cursor, s.records.len() as u64, "{}: VR consumed the whole import", s.name);
    let open =
        openOutputCall::abi_decode_returns(&view(after, openOutputCall {}.abi_encode())).unwrap();
    assert_eq!(open, e.open_output, "{}: open output", s.name);
    let acked =
        lastAckedCall::abi_decode_returns(&view(after, lastAckedCall {}.abi_encode())).unwrap();
    assert_eq!(acked, e.last_acked, "{}: last acknowledged", s.name);
    let module = view(after, activeModuleCall {}.abi_encode());
    assert_eq!(Address::from_slice(&module[12..32]), e.active_module, "{}: module", s.name);
}

// ---- the tests --------------------------------------------------------------------------------

/// The pinned code: the registry the genesis carries is the contracts-main `SealRegistry` ureth
/// pins, and the VR hashes the fixture carries are reported (VT-14 pins them).
#[test]
fn the_fixture_runs_contracts_main_bytecode() {
    let genesis: serde_json::Value =
        serde_json::from_str(include_str!("../testdata/signed-beacon-genesis.json")).unwrap();
    let code: Bytes = genesis["alloc"]["0xff00000000000000000000000000000000000002"]["code"]
        .as_str()
        .unwrap()
        .parse()
        .unwrap();
    assert_eq!(keccak256(&code), SEAL_REGISTRY_CODE_HASH);
    println!("vr-hook: SealRegistry 0xff..02 runtime {SEAL_REGISTRY_CODE_HASH}");
    for a in &fixture().accounts {
        println!(
            "vr-hook: {:<16} {} runtime {} ({} bytes)",
            a.role,
            a.address,
            keccak256(&a.code),
            a.code.len()
        );
        assert!(a.code.len() <= 24_576, "{}: EIP-170", a.role);
    }
    for role in ["vr", "governanceFacet", "repairFacet", "recordsFacet", "poa", "composer"] {
        let a = account(role);
        let high = a.as_slice()[0];
        assert_eq!(high, 0xff, "{role} sits at its genesis address");
    }
    assert_eq!(account("vr"), VR);
}

/// Every scenario through the real block path: the block builds at the provisional pins with the
/// system budget at exactly the base plus the hook envelope, replays to itself, and leaves VR and
/// the modules in exactly the state forge computed; the hook reports forge's outcome.
#[test]
fn every_scenario_reproduces_forge_through_the_block_path() {
    assert!(fixture().scenarios.len() >= 27);
    for s in &fixture().scenarios {
        let world = World::new(s);
        let hook = pinned(s);
        let (built, after) = world
            .build(hook)
            .unwrap_or_else(|e| panic!("{}: the block must stay valid: {e}", s.name));
        let d = diff(&after, s);
        assert!(d.is_empty(), "{}: state differs from forge:\n{}", s.name, d.join("\n"));
        check_views(&after, s);
        let replay = replay_complete(
            &world.config(hook),
            world.provider.clone(),
            &world.provider,
            &built.outcome.block,
        )
        .unwrap_or_else(|e| panic!("{}: replay: {e}", s.name));
        assert_eq!(replay.output.result, built.outcome.execution_result, "{}", s.name);

        // the same hook run directly reports forge's outcome and lands on the same state
        let (before, env) = world.before_hooks();
        let budget = hook.envelope_gas().unwrap();
        let (outcome, direct) = hooks_on(&before, &env, &hook, budget).unwrap();
        assert_eq!(outcome.applied, s.expect.applied, "{}: applied", s.name);
        assert_eq!(outcome.elected, Some(s.expect.outcome), "{}: elect outcome", s.name);
        assert!(diff(&direct, s).is_empty(), "{}: the direct run differs", s.name);
        assert!(outcome.gas_spent <= budget);
        // a node that pins no hook computes another state and refuses the block
        if !s.records.is_empty() || s.expect.outcome != 1 {
            assert!(
                replay_complete(
                    &world.config(RecordsHook::default()),
                    world.provider.clone(),
                    &world.provider,
                    &built.outcome.block
                )
                .is_err(),
                "{}",
                s.name
            );
        }
    }
}

/// Containment at the hook: every misbehaving module leaves a valid block, VR Faulted (or, for the
/// absorbed re-entry and the cap griefing, healthy) and the cursor advanced by exactly the batch.
#[test]
fn a_misbehaving_module_never_invalidates_the_block() {
    // (scenario, what the module does, elect outcome, health)
    let cases: &[(&str, &str, u8, u8)] = &[
        ("elect-revert", "elect reverts", 3, 1),
        ("elect-oog", "elect burns its whole cap", 3, 1),
        ("elect-malformed", "elect returns 65 malformed bytes", 3, 1),
        ("elect-huge", "elect returns 1 MiB", 3, 1),
        ("elect-write-revert", "elect writes, then reverts", 3, 1),
        ("elect-reenter-bubble", "elect re-enters publish and bubbles the revert", 3, 1),
        ("elect-reenter", "elect re-enters all 12 mutators (each refused), then answers", 2, 0),
        ("elect-grief", "elect burns to 20,000 below its cap, then answers", 2, 0),
        ("output-malformed", "outputOf of a ready reservation is malformed", 3, 1),
        ("output-huge", "outputOf returns 1 MiB", 3, 1),
        ("output-invalid", "outputOf serves a Ready output VR's validation rejects", 3, 1),
        ("records-revert", "onRecords reverts in the Ack + Boundary batch", 1, 1),
        ("records-oog", "onRecords burns its cap", 1, 1),
        ("records-huge", "onRecords returns 1 MiB", 1, 1),
        ("records-word", "onRecords (a void step) returns a word", 1, 1),
        ("records-reenter", "onRecords re-enters publish and bubbles", 1, 1),
        ("resolved-revert", "onResolved reverts at the Boundary", 1, 1),
        ("resolved-oog", "onResolved burns its cap", 1, 1),
        ("attach-revert", "the new module's attach reverts at the switch", 1, 1),
    ];
    for (name, what, outcome, health) in cases {
        let s = scenario(name);
        assert_eq!((s.expect.outcome, s.expect.health), (*outcome, *health), "{name}: forge");
        let world = World::new(s);
        let (built, after) = world
            .build(pinned(s))
            .unwrap_or_else(|e| panic!("{name} ({what}) invalidated the block: {e}"));
        assert!(diff(&after, s).is_empty(), "{name}");
        assert_eq!(health_of(&after), *health, "{name}: {what}");
        let (before, env) = world.before_hooks();
        let hook = pinned(s);
        let (o, _) = hooks_on(&before, &env, &hook, hook.envelope_gas().unwrap()).unwrap();
        assert_eq!(o.elected, Some(*outcome), "{name}");
        assert_eq!(o.applied, s.records.len() as u64, "{name}: the cursor moved by the batch");
        println!(
            "vr-hook: containment {name:<22} {what}: block valid, outcome {outcome}, health {health}, header gas {}",
            built.outcome.execution_result.gas_used
        );
    }
    // the write a reverting module made rolled back with its frame
    let s = scenario("elect-write-revert");
    let mock = account("mock");
    assert_eq!(
        s.pre.get(&mock).map(|p| p.len()),
        s.post.get(&mock).map(|p| p.len()),
        "the module's partial write is not in the post state"
    );
    // a fault left no reservation behind
    for name in ["elect-revert", "output-malformed", "output-invalid"] {
        let s = scenario(name);
        let (_, after) = World::new(s).build(pinned(s)).unwrap();
        assert_eq!(output_state(&after, keccak256("R")), 0, "{name}: R was never reserved");
    }
}

/// Record kinds 6 to 8 apply through the hook: Boundary installs and activates, `OutputRejected`
/// rejects then `SessionClosed` closes (with `PoA` parking the joiner), `HolderRetirement` marks.
#[test]
fn record_kinds_six_to_eight_apply_through_the_hook() {
    let s = scenario("holder-batch");
    let kinds: Vec<u8> = s.records.iter().map(|r| r.kind).collect();
    assert_eq!(
        kinds,
        vec![2, 6, 8, 4, 8],
        "Ack, Boundary, HolderRetirement, Closure, HolderRetirement"
    );
    let (_, after) = World::new(s).build(pinned(s)).unwrap();
    for (id, generation) in [(2u64, 1u64), (3, 1)] {
        let out = view(&after, retiredCall { holder: 0, id, generation }.abi_encode());
        assert!(retiredCall::abi_decode_returns(&out).unwrap(), "({id}, {generation}) retired");
    }
    let out = view(&after, retiredCall { holder: 0, id: 4, generation: 1 }.abi_encode());
    assert!(!retiredCall::abi_decode_returns(&out).unwrap());
    assert_eq!(output_state(&after, keccak256("R")), 5, "R Acknowledged");
    assert_eq!(health_of(&after), 0, "no anomaly");

    let s = scenario("poa-rejected");
    let kinds: Vec<u8> = s.records.iter().map(|r| r.kind).collect();
    assert_eq!(kinds, vec![7, 1], "OutputRejected(Expired), SessionClosed");
    let (_, before) = World::new(s).build(RecordsHook::default()).unwrap();
    let (_, after) = World::new(s).build(pinned(s)).unwrap();
    let rid = B256::from(s.records[0].data[..32].try_into().map(|a: [u8; 32]| a).unwrap());
    assert_eq!(output_state(&before, rid), 2, "Published before the block");
    assert_eq!(output_state(&after, rid), 7, "Closed after it");
    assert_eq!(health_of(&after), 0);
    // the PoA module's state moved (the joiner parked): its storage changed in the block
    let poa = account("poa");
    assert_ne!(s.pre.get(&poa), s.post.get(&poa), "PoA saw the rejection");
}

/// The pointer switch through the hook: `PoA` to a fresh `PoA` instance at the Boundary, the old
/// module fed its records first; and a switch to a module whose attach fails leaves VR Faulted with
/// the pointer moved and no holder entry consumed.
#[test]
fn the_module_switch_works_through_the_hook() {
    let s = scenario("poa-switch");
    let (before, _) = World::new(s).before_hooks();
    let (_, after) = World::new(s).build(pinned(s)).unwrap();
    let module = |st: &FixtureProvider| {
        let out = view(st, activeModuleCall {}.abi_encode());
        Address::from_slice(&out[12..32])
    };
    assert_eq!(module(&before), account("poa"));
    assert_eq!(module(&after), account("poaNext"));
    assert_eq!(health_of(&after), 0);
    assert!(
        !s.pre.contains_key(&account("poaNext")) && s.post.contains_key(&account("poaNext")),
        "attach wrote the new module's committee"
    );

    let s = scenario("attach-revert");
    let (_, after) = World::new(s).build(pinned(s)).unwrap();
    assert_eq!(module(&after), account("mockNext"));
    assert_eq!(health_of(&after), 1, "Faulted: repair mode follows");
    let out = view(&after, holderCountCall {}.abi_encode());
    assert_eq!(holderCountCall::abi_decode_returns(&out).unwrap(), 0);
}

/// The smallest `g` in `[lo, hi]` for which `ok` holds (monotone), to 1,000 gas.
fn threshold(mut lo: u64, mut hi: u64, ok: impl Fn(u64) -> bool) -> u64 {
    assert!(ok(hi), "not even {hi} suffices");
    while hi - lo > 1_000 {
        let mid = lo + (hi - lo) / 2;
        if ok(mid) {
            hi = mid;
        } else {
            lo = mid;
        }
    }
    hi
}

/// Gas against the provisional pins: each scenario's records and election cost, measured on the
/// hook's own meter, and the smallest reservation at which the hook still reproduces forge (below
/// it a contained step is `BudgetShort` or VR runs out of gas), all within `HookRecordGas` per
/// record and `ElectGas`.
#[test]
fn hook_gas_stays_within_the_provisional_profile_pins() {
    println!(
        "vr-hook: provisional pins: ElectGas {ELECT_GAS} (elect step at VR caps {} x 5/4), HookRecordGas {HOOK_RECORD_GAS} per record",
        elect_need(CAP_ELECT, CAP_OUTPUT)
    );
    println!(
        "vr-hook: {:<22} {:>3} {:>10} {:>10} {:>11} {:>11}",
        "scenario", "n", "records", "elect", "min records", "min elect"
    );
    let mut worst_elect = (0u64, "");
    let mut worst_record = (0u64, "");
    for s in &fixture().scenarios {
        let world = World::new(s);
        let (before, env) = world.before_hooks();
        let n = s.records.len() as u64;
        let hook = pinned(s);
        // the records step alone, then both steps: the election's cost is the difference
        let records_only = RecordsHook { election: Address::ZERO, elect_gas: 0, ..hook };
        let (r, reference) =
            hooks_on(&before, &env, &records_only, records_only.envelope_gas().unwrap()).unwrap();
        let (both, _) = hooks_on(&before, &env, &hook, hook.envelope_gas().unwrap()).unwrap();
        let records_gas = r.gas_spent;
        let elect_gas = both.gas_spent - r.gas_spent;
        assert!(records_gas <= HOOK_READS_GAS + n.max(1) * HOOK_RECORD_GAS, "{}", s.name);
        assert!(elect_gas <= ELECT_GAS, "{}: elect {elect_gas}", s.name);

        // the smallest budget for the records step that still lands on the reference state
        let min_records = if n == 0 {
            0
        } else {
            threshold(0, records_only.envelope_gas().unwrap(), |budget| {
                hooks_on(&before, &env, &records_only, budget)
                    .map(|(o, st)| {
                        o.applied == n &&
                            fixture().accounts.iter().all(|a| {
                                st.storage_of(a.address) == reference.storage_of(a.address)
                            })
                    })
                    .unwrap_or(false)
            })
        };
        // the smallest elect reservation that still reproduces forge's outcome and state
        let min_elect = threshold(1, ELECT_GAS, |g| {
            let h = RecordsHook { elect_gas: g, ..hook };
            hooks_on(&before, &env, &h, h.envelope_gas().unwrap())
                .map(|(o, st)| o.elected == Some(s.expect.outcome) && diff(&st, s).is_empty())
                .unwrap_or(false)
        });
        assert!(min_records <= HOOK_READS_GAS + n * HOOK_RECORD_GAS, "{}", s.name);
        assert!(min_elect <= ELECT_GAS, "{}", s.name);
        if n > 0 && min_records / n > worst_record.0 {
            worst_record = (min_records / n, &s.name);
        }
        if min_elect > worst_elect.0 {
            worst_elect = (min_elect, &s.name);
        }
        println!(
            "vr-hook: {:<22} {:>3} {:>10} {:>10} {:>11} {:>11}",
            s.name, n, records_gas, elect_gas, min_records, min_elect
        );
    }
    println!(
        "vr-hook: worst min elect {} ({}) against ElectGas {ELECT_GAS}; worst min records per record {} ({}) against HookRecordGas {HOOK_RECORD_GAS}",
        worst_elect.0, worst_elect.1, worst_record.0, worst_record.1
    );
}

/// An under-priced election is contained too: below the contained step's requirement VR reports
/// `BudgetShort` and answers Disabled (no reservation, no fault), and the block stays valid. That
/// is a mis-pinned profile (an acceptance failure for the pin), never a chain halt.
#[test]
fn an_election_priced_below_the_step_budget_is_disabled_not_invalid() {
    let s = scenario("poa-elect");
    let world = World::new(s);
    let (before, env) = world.before_hooks();
    let hook = RecordsHook { elect_gas: 2_000_000, ..pinned(s) };
    let (o, after) = hooks_on(&before, &env, &hook, hook.envelope_gas().unwrap()).unwrap();
    assert_eq!(o.elected, Some(0), "BudgetShort: Disabled");
    assert_eq!(health_of(&after), 0, "no fault for a short budget");
    let open =
        openOutputCall::abi_decode_returns(&view(&after, openOutputCall {}.abi_encode())).unwrap();
    assert_eq!(open, B256::ZERO);
    assert!(world.build(hook).is_ok(), "the block stays valid");
}
